// Sediakan PDF base64 dari binary attachment Gmail
// n8n 2.x guna filesystem-v2 binary mode — mesti guna getBinaryDataBuffer
// (item.binary.attachment_0.data cuma pointer "filesystem-v2", bukan data!)

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binary = item.binary || {};
  const keys = Object.keys(binary);
  if (keys.length === 0) continue;

  // Cari attachment PDF (biasanya statement)
  for (const k of keys) {
    const b = binary[k];
    if (!b) continue;
    const name = (b.fileName || k).toLowerCase();
    const isPdf = b.mimeType === 'application/pdf' || name.endsWith('.pdf');
    if (isPdf) {
      // Fungsi rasmi n8n untuk dapat binary buffer sebenar
      const buffer = await this.helpers.getBinaryDataBuffer(i, k);
      results.push({
        json: {
          pdf_base64: buffer.toString('base64'),   // base64 sebenar
          bank: 'maybank',
          accountId: '<ACCOUNT_ID>',
          filename: b.fileName || k
        }
      });
      break;
    }
  }
}

if (results.length === 0) {
  throw new Error('No PDF attachment found in email');
}

return results;

// Map hasil /extract (JSON transaksi) ke format Actual Budget
const extracted = $json.transactions || [];
if (extracted.length === 0) {
  throw new Error('No transactions extracted from statement');
}

// Account ID Maybank (dari /accounts)
const accountId = '<ACCOUNT_ID>';

// Tukar RM (float) ke sen (integer) — Actual guna integer cents
// amount positif = masuk (deposit), negatif = keluar (withdrawal)
const transactions = extracted.map(tx => {
  const amountSen = Math.round((tx.amount || 0) * 100);
  return {
    date: tx.date,
    amount: amountSen,
    payee_name: tx.description || 'Unknown',
    // imported_id: gabungan tarikh+amount+description utk dedup
    imported_id: [tx.date, Math.abs(amountSen), (tx.description || '').replace(/\s+/g, '_')].join('-'),
    notes: tx.balance_after != null ? 'Balance: ' + tx.balance_after : undefined
  };
});

return [{
  json: {
    accountId,
    transactions
  }
}];

// Nota: workflow selesai. Log hasil untuk rujukan.
const result = $json;
return [{
  json: {
    imported: result.added ? result.added.length : 0,
    updated: result.updated ? result.updated.length : 0,
    errors: result.errors || [],
    message: 'Statement imported to Actual Budget'
  }
}];
